-- Uldum spawns, part 7 of 8: the rows of this part are deleted by key range before they are inserted, so the file can run twice.
-- Based on Legends of Azeroth 5.4.8 and The Cataclysm Preservation Project 4.3.4.

DELETE FROM `waypoint_data` WHERE (`id` > 91228970 OR (`id` = 91228970 AND `point` >= 4)) AND (`id` < 91246660 OR (`id` = 91246660 AND `point` <= 5));





